  // Generate nullifier with nonce
  const nullifier = hash(secretKey, userNonce);

  // Verify hasn't participated in this round
  assert(!roundNullifiers[round].member(nullifier));

  // Register
  roundNullifiers[round].insert(nullifier);
}

